WITH high_links AS (
 SELECT DISTINCT tl.tgt_id AS urs_id, tl.src_id AS risk_id FROM pd.trace_link tl JOIN pd.val_risk_item r ON r.ri_id=tl.src_id AND r.risk_class='HIGH' WHERE tl.src_type='RISK' AND tl.tgt_type='SPEC' AND tl.tgt_id LIKE 'URS-%'
)
SELECT urs_id, string_agg(risk_id, ', ' ORDER BY risk_id) risks FROM high_links GROUP BY urs_id ORDER BY urs_id;
